const listMailingContacts = `-- name: ListMailingContacts :many
WITH hits AS (
    -- Matches on the person: uses the contact trigram indexes.
    SELECT cc.id
    FROM customer_contacts cc
    WHERE cc.tenant_id = $1::bigint
      AND cc.email <> ''
      AND cc.status = 'ACTIVE'
      AND cc.email_permission = 'ALLOWED'
      AND (cc.name ILIKE '%' || $2::text || '%'
           OR cc.email ILIKE '%' || $2::text || '%')
    UNION
    -- Matches on the company: uses the customer trigram index, then joins.
    SELECT cc.id
    FROM customers c
    JOIN customer_contacts cc
      ON cc.customer_id = c.id AND cc.tenant_id = c.tenant_id
    WHERE c.tenant_id = $1::bigint
      AND cc.email <> ''
      AND cc.status = 'ACTIVE'
      AND cc.email_permission = 'ALLOWED'
      AND c.name ILIKE '%' || $2::text || '%'
)
SELECT
    cc.id           AS contact_id,
    cc.name,
    cc.title,
    cc.email,
    cc.is_primary,
    c.id            AS customer_id,
    c.name          AS customer_name,
    c.country,
    c.country_code,
    cc.language,
    cc.email_categories
FROM customer_contacts cc
JOIN customers c ON c.id = cc.customer_id AND c.tenant_id = cc.tenant_id
WHERE cc.tenant_id = $1::bigint
  AND c.status = 'ACTIVE'
  AND cc.email <> ''
  AND cc.status = 'ACTIVE'
  AND cc.email_permission = 'ALLOWED'
  -- An empty keyword lists the book; anything else must have matched above.
  AND ($2::text = '' OR cc.id IN (SELECT id FROM hits))
  AND (
      cardinality($3::bigint[]) = 0
      OR c.id = ANY($3::bigint[])
  )
ORDER BY c.name, cc.is_primary DESC, cc.sort_order, cc.id
LIMIT 500
`

type ListMailingContactsParams struct {
	TenantID    int64
	Keyword     string
	CustomerIds []int64
}

type ListMailingContactsRow struct {
	ContactID       int64
	Name            string
	Title           string
	Email           string
	IsPrimary       bool
	CustomerID      int64
	CustomerName    string
	Country         string
	CountryCode     string
	Language        string
	EmailCategories []string
}

// The address book for the mail composer.
//
// The OR is split into a UNION on purpose. Written as one predicate the three
// ILIKE conditions span two tables, and Postgres cannot use an index for an
// OR that crosses a join — it has to join first and filter every pair, which
// is a sequential scan however many trigram indexes exist. Each UNION branch
// touches one table, so each can use its own index.
//
// Contacts without an email are left out rather than returned greyed: a
// picker row you cannot pick is noise. Deactivated customers likewise.
func (q *Queries) ListMailingContacts(ctx context.Context, arg ListMailingContactsParams) ([]ListMailingContactsRow, error) {
	rows, err := q.db.Query(ctx, listMailingContacts, arg.TenantID, arg.Keyword, arg.CustomerIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListMailingContactsRow
	for rows.Next() {
		var i ListMailingContactsRow
		if err := rows.Scan(
			&i.ContactID,
			&i.Name,
			&i.Title,
			&i.Email,
			&i.IsPrimary,
			&i.CustomerID,
			&i.CustomerName,
			&i.Country,
			&i.CountryCode,
			&i.Language,
			&i.EmailCategories,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

