const updateSupplier = `-- name: UpdateSupplier :one
UPDATE suppliers
SET name = $3, country = $4, address = $5, currency = $6,
    contact_name = $7, contact_phone = $8, contact_email = $9, remark = $10,
    updated_by = $11, updated_at = now()
WHERE tenant_id = $1 AND id = $2
RETURNING id, tenant_id, code, name, country, address, currency, contact_name, contact_phone, contact_email, remark, status, created_at, created_by, updated_at, updated_by
`

type UpdateSupplierParams struct {
	TenantID     int64
	ID           int64
	Name         string
	Country      string
	Address      string
	Currency     string
	ContactName  string
	ContactPhone string
	ContactEmail string
	Remark       string
	UpdatedBy    int64
}

func (q *Queries) UpdateSupplier(ctx context.Context, arg UpdateSupplierParams) (Supplier, error) {
	row := q.db.QueryRow(ctx, updateSupplier,
		arg.TenantID,
		arg.ID,
		arg.Name,
		arg.Country,
		arg.Address,
		arg.Currency,
		arg.ContactName,
		arg.ContactPhone,
		arg.ContactEmail,
		arg.Remark,
		arg.UpdatedBy,
	)
	var i Supplier
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Code,
		&i.Name,
		&i.Country,
		&i.Address,
		&i.Currency,
		&i.ContactName,
		&i.ContactPhone,
		&i.ContactEmail,
		&i.Remark,
		&i.Status,
		&i.CreatedAt,
		&i.CreatedBy,
		&i.UpdatedAt,
		&i.UpdatedBy,
	)
	return i, err
}
